import{_ as i,o as a,c as n,ai as e}from"./chunks/framework.Ai2o9gNv.js";const p="/assets/image-20250912223718457.BALA7LBG.png",l="/assets/image-20250912225121290.DGIoKkIi.png",t="/assets/image-20250822223258675.CJHnmYEl.png",h="/assets/wanshaoweixin.DWzIcicW.jpg",m=JSON.parse('{"title":"可可图片编辑 HarmonyOS（7）图片绘画","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/可可图片编辑/可可图片编辑 HarmonyOS（7）图片绘画/可可图片编辑 HarmonyOS（7）图片绘画.md","filePath":"鸿蒙开发技巧/可可图片编辑/可可图片编辑 HarmonyOS（7）图片绘画/可可图片编辑 HarmonyOS（7）图片绘画.md","lastUpdated":1757689175000,"__rawMarkdown":"# 可可图片编辑 HarmonyOS（7）图片绘画\\n\\n## 前言\\n\\n可可图片编辑 实现 在上传图片，然后在已有图片上绘画的功能。\\n\\n该功能主要也是利用了canvas画布功能，把选择的图片 转换成画布，然后在上面直接描绘。\\n\\n![image-20250912223718457](assets/image-20250912223718457.png)\\n\\n\\n\\n\\n\\n## 使用 canvas 的 drawImage 描绘图片\\n\\n演示如何通过CanvasRenderingContext2D的drawImage方法实现**图片渲染及尺寸控制**\\n\\n1. **创建渲染上下文**\\n\\n   - 通过`RenderingContextSettings`配置抗锯齿属性（true表示启用）\\n   - 初始化`CanvasRenderingContext2D`对象，作为2D绘图的入口\\n\\n2. **加载图片资源**\\n\\n   - 使用`ImageBitmap`全局类加载本地图片资源（\\"images/1.jpg\\"）\\n   - 创建位图对象后可直接用于Canvas绘制，相比Image组件更适用于像素级操作\\n\\n3. **构建UI布局**\\n\\n   - 通过`Column`容器创建垂直布局\\n   - 设置Canvas组件尺寸为100%宽度+固定高度，背景色为浅灰色\\n   - 使用`.onReady`生命周期回调确保Canvas初始化完成后执行绘制操作\\n\\n4. **执行绘制操作**\\n\\n   - **基础绘制**：`drawImage(this.img, 0, 0)`将图片绘制在Canvas左上角（0,0）位置\\n\\n   - 缩放绘制：`drawImage(this.img, 0, 150, 200, 150)`\\n\\n     指定绘制区域，实现：\\n\\n     - 源图片按原始比例缩放至200x150像素\\n     - 绘制起点位于Canvas坐标(0,150)处\\n\\n   - 两种调用方式分别对应W3C标准的drawImage重载方法：\\n\\n     - drawImage(image, dx, dy)\\n     - drawImage(image, dx, dy, dWidth, dHeight)\\n\\n\\n\\n![image-20250912225121290](assets/image-20250912225121290.png)\\n\\n**示例代码**\\n\\n```typescript\\n@Entry\\n@Component\\nstruct CanvasDrawImageExample {\\n  // 1. 创建Canvas渲染上下文\\n  private settings: RenderingContextSettings = new RenderingContextSettings(true);\\n  private context: CanvasRenderingContext2D = new CanvasRenderingContext2D(this.settings);\\n  // 2. 创建图片对象 - 注意：ImageBitmap是全局类，不从image命名空间导出\\n  private img: ImageBitmap = new ImageBitmap(\\"images/1.jpg\\"); //默认的图片\\n\\n  build() {\\n    Column() {\\n      // 3. 创建Canvas组件\\n      Canvas(this.context)\\n        .width(\'100%\')\\n        .height(400)\\n        .backgroundColor(\'#F1F3F5\')\\n        .onReady(() => {\\n          // 4. 在Canvas准备就绪后绘制图片\\n          this.context.drawImage(this.img, 0, 0);\\n          this.context.drawImage(this.img, 0, 150, 200, 150);\\n        })\\n    }\\n    .width(\'100%\')\\n    .padding(10)\\n  }\\n}\\n\\n```\\n\\n## 使用 canvas 使用 PixelMap 绘制图片\\n\\n实现图片资源的异步加载与Canvas上的自定义绘制，支持图片缩放/位置控制。\\n主要逻辑：\\n\\n1. **模块导入**\\n\\n   - 通过`@kit.ImageKit`引入鸿蒙系统的图像处理能力，用于操作PixelMap像素数据。\\n\\n2. **组件定义**\\n\\n   - 使用`@Entry`标记为应用入口组件，`@Component`声明为自定义组件。\\n   - 创建`CanvasRenderingContext2D`渲染上下文，配置抗锯齿（`RenderingContextSettings(true)`）。\\n\\n3. **资源预加载**\\n\\n   - 在 `aboutToAppear`\\n\\n     生命周期中：\\n\\n     - 调用`image.createImageSource`创建图片源（沙箱路径需替换为实际地址）。\\n     - 通过`createPixelMap()`异步生成像素数据，赋值给`pixelMap`变量。\\n\\n4. **Canvas绘制**\\n\\n   - 在`build`函数中构建UI，设置Canvas尺寸与背景色。\\n\\n   - 通过 `onReady`\\n\\n     回调确保Canvas初始化完成后：\\n\\n     - 检测`pixelMap`是否加载完成（避免空指针）。\\n     - 调用`drawImage`绘制图片，参数`0,0,300,200`表示将图片缩放至300x200尺寸并绘制到Canvas左上角。\\n\\n**示例代码**\\n\\n```typescript\\nimport { image } from \'@kit.ImageKit\';\\n\\n@Entry\\n@Component\\nstruct CanvasDrawPixelMapExample {\\n  private settings: RenderingContextSettings = new RenderingContextSettings(true);\\n  private context: CanvasRenderingContext2D = new CanvasRenderingContext2D(this.settings);\\n  private pixelMap: image.PixelMap | undefined = undefined;\\n\\n  // 组件初始化时加载图片\\n  aboutToAppear() {\\n    // 创建ImageSource并获取PixelMap\\n    let imageSource = image.createImageSource(\\"沙箱图片地址\\");\\n    imageSource.createPixelMap().then((pixelMap) => {\\n      this.pixelMap = pixelMap;\\n    });\\n  }\\n\\n  build() {\\n    Column() {\\n      Canvas(this.context)\\n        .width(\'100%\')\\n        .height(400)\\n        .backgroundColor(\'#F1F3F5\')\\n        .onReady(() => {\\n          // 检查pixelMap是否已加载\\n          if (this.pixelMap) {\\n            // 使用PixelMap绘制图片\\n            this.context.drawImage(this.pixelMap, 0, 0, 300, 200);\\n          }\\n        })\\n    }\\n    .width(\'100%\')\\n    .padding(10)\\n  }\\n}\\n\\n```\\n\\n## 以往文章\\n\\n- 我的iMaHarmonyOS 知识库接入 鸿蒙6 API20 新特性了 \\n\\n  > https://mp.weixin.qq.com/s/YsbFQyi5PsndpRUaA9h_dA?token=830743671&lang=zh_CN\\n\\n- 鸿蒙创新赛 HarmonyOS 6.0.0(20) 关键特性汇总\\n\\n  > https://mp.weixin.qq.com/s/ERmgSAIT8B8njFqtyPx9IQ\\n\\n- 可可图片编辑 HarmonyOS（4）图片裁剪-canvas\\n\\n  > https://mp.weixin.qq.com/s/2M3f_LNnt0YRo0qEnCnqpA\\n\\n- 可可图片编辑 HarmonyOS（3）应用间分享图片\\n\\n  > https://mp.weixin.qq.com/s/n8kkdougB4lqDHjYC7co8g\\n\\n\\n\\n\\n\\n\\n\\n## 近期活动\\n\\n最近想要想要考取 HarmonyOS 基础或者高级证书，或者快要获取的同学都可以点击这个链接，[加入我的班级](https://developer.huawei.com/consumer/cn/training/classDetail/7e230b074eaa41c587c71c1d1a9a6514?type=1%3Fha_source%3Dhmosclass&ha_sourceId=89000248)，考取成功有机会获得鸿蒙礼盒一份。\\n\\n> https://developer.huawei.com/consumer/cn/training/classDetail/7e230b074eaa41c587c71c1d1a9a6514?type=1%3Fha_source%3Dhmosclass&ha_sourceId=89000248\\n\\n![](assets/image-20250822223258675.png)\\n\\n\\n\\n## 联系我\\n\\n可以加我微信，带你了解更多HarmonyOS相关的资讯。\\n\\n![](assets/wanshaoweixin.jpg)"}'),k={name:"鸿蒙开发技巧/可可图片编辑/可可图片编辑 HarmonyOS（7）图片绘画/可可图片编辑 HarmonyOS（7）图片绘画.md"};function r(E,s,d,g,o,c){return a(),n("div",null,[...s[0]||(s[0]=[e("",25)])])}const C=i(k,[["render",r]]);export{m as __pageData,C as default};
